object MasterCatalogSeeder {
    const val CURRENT_CATALOG_VERSION = 1

    private fun p(
        id: Int,
        catCode: String,
        catEn: String,
        catTa: String,
        nameEn: String,
        nameTa: String,
        unit: String,
        icon: String
    ): MasterProductEntity {
        val m = CatalogMetadataV3.metaFor(id, unit)
        return MasterProductEntity(
            productId = id,
            categoryCode = catCode,
            categoryEn = catEn,
            categoryTa = catTa,
            nameEn = nameEn,
            nameTa = nameTa,
            defaultUnit = unit,
            iconResName = icon,
            catalogVersion = CURRENT_CATALOG_VERSION,
            shapeCode = m.shapeCode,
            colorCode = m.colorCode,
            sizeRank = m.sizeRank,
            weightRank = m.weightRank,
            searchKeywords = m.searchKeywords,
            isPerishable = m.isPerishable,
            defBundleMilli = m.defBundleMilli,
            unitStepMode = m.unitStepMode,
            isArchived = false
        )
    }

